                work += X + 1
        elif kind == "member":
            if item[3]:
                work += X + 1
            else:
                work += X + sum(egress_queues[item[2]]) + 1
        elif kind == "service":
            work += X + sum(egress_queues[item[2]]) + 1
        elif kind == "reload":
