            work += (
                X
                + D
                + P
                + len(item[3])
                + sum(len(entry["static"]) for entry in item[4])
                + 1
            )
        else:  # 帧：S 取入端口排队帧数
            work += X + 3 * P + M + R + D + sum(egress_queues[item[2]]) + 1
        if work > limit:
            raise ReloadWorkLimit
